//! Embedded core schema packs.
//!
//! One gzipped JSON array of FHIR Schemas per enabled FHIR version,
//! generated by the `generate-schema-packs` binary from the spec bundles in
//! `crates/fhir-gen/resources/` and committed under `packs/` (the same
//! committed-generated-artifact workflow as the fhir-gen models).
//!
//! Registries are built lazily, once per process per version.

use crate::resolver::SchemaRegistry;
use crate::schema::FhirSchema;
use flate2::read::GzDecoder;
use helios_fhir::FhirVersion;
use std::io::Read;
use std::sync::{Arc, OnceLock};

#[cfg(feature = "R4")]
static R4_PACK: &[u8] = include_bytes!("../packs/fhir_schemas_r4.json.gz");
#[cfg(feature = "R4B")]
static R4B_PACK: &[u8] = include_bytes!("../packs/fhir_schemas_r4b.json.gz");
#[cfg(feature = "R5")]
static R5_PACK: &[u8] = include_bytes!("../packs/fhir_schemas_r5.json.gz");
#[cfg(feature = "R6")]
static R6_PACK: &[u8] = include_bytes!("../packs/fhir_schemas_r6.json.gz");

/// The embedded core registry for a FHIR version. Parsed on first use;
/// subsequent calls return the shared instance.
pub fn core_registry(version: FhirVersion) -> Arc<SchemaRegistry> {
    match version {
        #[cfg(feature = "R4")]
        FhirVersion::R4 => {
            static REG: OnceLock<Arc<SchemaRegistry>> = OnceLock::new();
            Arc::clone(REG.get_or_init(|| Arc::new(load_pack(R4_PACK))))
        }
        #[cfg(feature = "R4B")]
        FhirVersion::R4B => {
            static REG: OnceLock<Arc<SchemaRegistry>> = OnceLock::new();
            Arc::clone(REG.get_or_init(|| Arc::new(load_pack(R4B_PACK))))
        }
        #[cfg(feature = "R5")]
        FhirVersion::R5 => {
            static REG: OnceLock<Arc<SchemaRegistry>> = OnceLock::new();
            Arc::clone(REG.get_or_init(|| Arc::new(load_pack(R5_PACK))))
        }
        #[cfg(feature = "R6")]
        FhirVersion::R6 => {
            static REG: OnceLock<Arc<SchemaRegistry>> = OnceLock::new();
            Arc::clone(REG.get_or_init(|| Arc::new(load_pack(R6_PACK))))
        }
        // Workspace feature unification can add FhirVersion variants beyond
        // the packs this crate was built with.
        #[allow(unreachable_patterns)]
        other => panic!(
            "no schema pack embedded for FHIR version {other:?} — enable the matching \
             helios-fhir-validator feature"
        ),
    }
}

/// Decompress and index a pack.
///
/// Insertion is two-pass — profiles (`derivation: constraint`) first, core
/// types and resources second — so that when a profile's `name` collides
/// with a core type name, the core schema wins the name alias. Canonical
/// URLs are unique and unaffected.
fn load_pack(bytes: &[u8]) -> SchemaRegistry {
    let mut decoder = GzDecoder::new(bytes);
    let mut json = Vec::new();
    decoder.read_to_end(&mut json).expect("embedded pack decompresses");
    let schemas: Vec<FhirSchema> =
        serde_json::from_slice(&json).expect("embedded pack parses");

    let mut registry = SchemaRegistry::new();
    let (profiles, core): (Vec<_>, Vec<_>) = schemas
        .into_iter()
        .partition(|s| s.derivation.as_deref() == Some("constraint"));
    for schema in profiles.into_iter().chain(core) {
        registry.insert(schema);
    }
    registry
}
